-- Storefront settings (P1-216, 04-api-spec.md §4). One row per shop; every
-- statement names the caller's tenant, and RLS holds it there too.

-- name: EnsureStorefrontSettings :exec
-- A shop made after the backfill gets its row on first use. The webhook id is
-- a random v4, generated by the caller: it sits in a URL.
INSERT INTO storefront_settings (tenant_id, midtrans_webhook_id)
VALUES (current_setting('app.tenant_id')::uuid, sqlc.arg(webhook_id))
ON CONFLICT (tenant_id) DO NOTHING;

-- name: GetStorefrontSettings :one
SELECT * FROM storefront_settings WHERE tenant_id = current_setting('app.tenant_id')::uuid;

-- name: LockStorefrontSettings :one
-- A PATCH validates the merged row under this lock, so two owners saving at
-- once cannot together switch off both payment methods.
SELECT * FROM storefront_settings WHERE tenant_id = current_setting('app.tenant_id')::uuid FOR UPDATE;

-- name: UpdateStorefrontSettings :one
UPDATE storefront_settings SET
    contact_email = sqlc.narg(contact_email),
    google_client_id = sqlc.narg(google_client_id),
    origin_postal_code = sqlc.narg(origin_postal_code),
    shipping_couriers = sqlc.arg(shipping_couriers),
    bank_transfer_enabled = sqlc.arg(bank_transfer_enabled),
    bank_transfer_instructions = sqlc.narg(bank_transfer_instructions),
    midtrans_enabled = sqlc.arg(midtrans_enabled),
    midtrans_environment = sqlc.narg(midtrans_environment),
    midtrans_client_key = sqlc.narg(midtrans_client_key),
    midtrans_server_key = sqlc.narg(midtrans_server_key),
    theme = sqlc.arg(theme),
    brand_color = sqlc.narg(brand_color),
    logo_r2_key = sqlc.narg(logo_r2_key),
    hero_r2_key = sqlc.narg(hero_r2_key),
    whatsapp_number = sqlc.narg(whatsapp_number),
    tagline = sqlc.narg(tagline),
    instagram = sqlc.narg(instagram),
    address = sqlc.narg(address),
    opening_hours = sqlc.narg(opening_hours),
    shopee_url = sqlc.narg(shopee_url),
    tokopedia_url = sqlc.narg(tokopedia_url),
    license = sqlc.narg(license),
    cancellation_policy = sqlc.narg(cancellation_policy),
    document_requirements = sqlc.narg(document_requirements),
    rebuild_hook_url = sqlc.narg(rebuild_hook_url),
    updated_at = now()
WHERE tenant_id = current_setting('app.tenant_id')::uuid
RETURNING *;

-- name: StorefrontConfig :one
-- What a website renders sign-in, payment and its look from (P1-224, P1-703,
-- P1-802). A shop with no settings row yet has the defaults: bank transfer on,
-- the katalog theme, nothing else.
SELECT t.name AS shop_name, s.google_client_id,
       coalesce(s.bank_transfer_enabled, true)::bool AS bank_transfer_enabled, s.bank_transfer_instructions,
       coalesce(s.midtrans_enabled, false)::bool AS midtrans_enabled, s.midtrans_environment, s.midtrans_client_key,
       coalesce(s.theme, 'katalog')::text AS theme, s.brand_color, s.logo_r2_key, s.hero_r2_key,
       s.whatsapp_number, s.tagline, s.instagram, s.address, s.opening_hours, s.shopee_url, s.tokopedia_url,
       s.license, s.cancellation_policy, s.document_requirements
FROM tenants t
LEFT JOIN storefront_settings s ON s.tenant_id = t.id
WHERE t.id = current_setting('app.tenant_id')::uuid;

-- name: FirstChangeSince :one
-- BR-098: the oldest write since the last rebuild that a static website shows:
-- the catalog, the blog, marketplace imports and the storefront settings.
SELECT created_at FROM audit_log
 WHERE created_at > sqlc.arg(since)::timestamptz
   AND split_part(action, '.', 1) IN ('product', 'variant', 'media', 'category', 'brand',
                                      'blog_post', 'blog_category', 'channel', 'storefront_settings')
 ORDER BY created_at
 LIMIT 1;

-- name: ClaimRebuild :one
-- One worker calls the hook: the claim holds only if no other moved
-- rebuild_last_at since this one read it. Not audited, so it is no change.
UPDATE storefront_settings SET rebuild_last_at = sqlc.arg(at), rebuild_last_status = NULL
 WHERE tenant_id = current_setting('app.tenant_id')::uuid AND rebuild_hook_url IS NOT NULL
   AND rebuild_last_at IS NOT DISTINCT FROM sqlc.narg(seen)::timestamptz
RETURNING rebuild_hook_url;

-- name: SetRebuildStatus :exec
UPDATE storefront_settings SET rebuild_last_status = sqlc.narg(status)
 WHERE tenant_id = current_setting('app.tenant_id')::uuid AND rebuild_last_at = sqlc.arg(at);
